                      OnMoveLeft="MoveToToDo"
                      OnMoveRight="MoveToDone"
                      OnAddTask="args => AddTask(args, "In Progress")" />

        <KanbanColumn ColumnName="Done"
                      Tasks="FilteredDoneTasks"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      OnMoveLeft="MoveToInProgress_FromDone"
                      OnAddTask="args => AddTask(args, "Done")" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private bool isLoading = true;
    private string? errorMessage;
    private string searchText = string.Empty;

    private List<TaskItem> ToDoTasks => allTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> InProgressTasks => allTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> DoneTasks => allTasks.Where(t => t.Status == "Done").ToList();

    private List<TaskItem> FilteredToDoTasks => ApplySearch(ToDoTasks);
    private List<TaskItem> FilteredInProgressTasks => ApplySearch(InProgressTasks);
    private List<TaskItem> FilteredDoneTasks => ApplySearch(DoneTasks);

    private int OverdueCount => allTasks.Count(t => t.DueDate < DateTime.Today);

    private List<TaskItem> ApplySearch(List<TaskItem> tasks)
    {
        if (string.IsNullOrWhiteSpace(searchText))
            return tasks;

        return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task MoveToInProgress(TaskItem task)
    {
        await UpdateStatus(task, "In Progress");
    }

    private async Task MoveToToDo(TaskItem task)
    {
        await UpdateStatus(task, "To Do");
    }

    private async Task MoveToDone(TaskItem task)
    {
        await UpdateStatus(task, "Done");
    }

    private async Task MoveToInProgress_FromDone(TaskItem task)
    {
        await UpdateStatus(task, "In Progress");
    }

    private async Task UpdateStatus(TaskItem task, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            var index = allTasks.FindIndex(t => t.Id == task.Id);
            if (index >= 0)
            {
                allTasks[index] = task with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task AddTask((string Title, string Assignee, string Priority, DateTime DueDate) formData, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(formData.Title, formData.Assignee, formData.Priority, formData.DueDate);
            allTasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

